#include <iostream>
#include <string>

constexpr int MAX = 30;
long long dp[MAX + 1][MAX + 1];

std::string find_kth(int A, int B, long long K) {
    if (A == 0) {
        return std::string(B, 'b');
    }
    if (B == 0) {
        return std::string(A, 'a');
    }
    if (K <= dp[A - 1][B]) {
        return std::string("a") + find_kth(A - 1, B, K);
    }
    else {
        return std::string("b") + find_kth(A, B - 1, K - dp[A - 1][B]);
    }
}

int main() {
    int A, B;
    long long K;
    std::cin >> A >> B >> K;
    dp[0][0] = 1;
    for (int i = 0; i <= A; ++i) {
        for (int j = 0; j <= B; ++j) {
            if (i > 0) {
                dp[i][j] += dp[i - 1][j];
            }
            if (j > 0) {
                dp[i][j] += dp[i][j - 1];
            }
        }
    }
    std::cout << find_kth(A, B, K) << '\n';
    return 0;
}

#include <iostream>
#include <vector>
#include <string>

int main() {
    int A, B;
    long long K;
    std::cin >> A >> B >> K;
    std::vector<std::vector<long long>> dp(A + 1, std::vector<long long>(B + 1));
    dp[0][0] = 1;
    for (int i = 0; i <= A; ++i) {
        for (int j = 0; j <= B; ++j) {
            if (i > 0) {
                dp[i][j] += dp[i - 1][j];
            }
            if (j > 0) {
                dp[i][j] += dp[i][j - 1];
            }
        }
    }
    while (A > 0 and B > 0) {
        if (K <= dp[A - 1][B]) {
            std::cout << 'a';
            A -= 1;
        }
        else {
            K -= dp[A - 1][B];
            std::cout << 'b';
            B -= 1;
        }
    }
    std::cout << std::string(A, 'a');
    std::cout << std::string(B, 'b');
    std::cout << '\n';
    return 0;
}
